import{c as t,Q as s,j as a,m as r}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"Password recovery","description":"How the forgot-password flow works, including token security and rate limits.","frontmatter":{"title":"Password recovery","description":"How the forgot-password flow works, including token security and rate limits."},"headers":[],"relativePath":"auth/password-recovery.md","filePath":"auth/password-recovery.md"}'),o={name:"auth/password-recovery.md"};function i(n,e,l,d,h,c){return s(),a("div",null,[...e[0]||(e[0]=[r('<p>Users who forget their password can request a reset link at <code>/forgot-password</code>. The link is sent to their email and expires after 30 minutes.</p><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><ol><li>User visits <code>/forgot-password</code> and enters their email.</li><li>GateKeeper responds with the same confirmation message regardless of whether the email matches a real account. This prevents an attacker from discovering which emails are registered.</li><li>If the email does match an account, GateKeeper generates a secure reset token, stores a hash of it in the database, and emails a link to the user.</li><li>The user clicks the link, which goes to <code>/reset-password?token=&lt;token&gt;</code>.</li><li>GateKeeper validates the token (checks it exists, is unexpired, and has not been used yet) and shows a password reset form.</li><li>The user sets a new password. GateKeeper marks the token as used, invalidates all existing sessions for that account, and redirects to <code>/login</code>.</li></ol><h2 id="token-security" tabindex="-1">Token security <a class="header-anchor" href="#token-security" aria-label="Permalink to &quot;Token security&quot;">​</a></h2><p>Reset tokens are 32 bytes of cryptographically random data, hex-encoded. GateKeeper stores the argon2id hash of the token, not the token itself. If the database is compromised, the stored hashes cannot be reversed into working tokens.</p><p>Tokens expire after 30 minutes. They are single-use: once a POST to <code>/reset-password</code> succeeds, the token is permanently invalidated.</p><p>A note on link preview bots: some email clients fetch links in emails automatically to generate previews. To prevent these bots from consuming a reset token before the user clicks it, GateKeeper only marks a token as used when the POST request succeeds, not when the GET request views the form.</p><h2 id="rate-limits" tabindex="-1">Rate limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate limits&quot;">​</a></h2><p>To prevent abuse:</p><ul><li>Maximum 3 reset requests per email address per hour.</li><li>Maximum 10 reset requests per IP address per hour.</li></ul><p>When a limit is hit, GateKeeper still shows the same generic confirmation message to the user. The actual email is simply not sent.</p><h2 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h2><p>Every reset request, successful reset, and invalid token attempt is recorded in the audit log with the event type and IP address.</p>',13)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
